function model(p) {
  // A health plan unifies 11 fictional member records from 4 systems. One deterministic match rule links
  // record pairs; union-find turns the pairs into profiles; the hidden truth (3 real people) scores the result.
  const rule = Math.max(0, Math.min(3, Math.round(p.rule)));
  const sf = Math.round(p.systemNames) === 1;
  const sources = sf ? [
    { id: 'portal', name: 'Experience Cloud', sub: 'member portal', icon: 'globe' },
    { id: 'contact', name: 'Health Cloud', sub: 'contact centre', icon: 'headset' },
    { id: 'claims', name: 'Claims system', sub: 'claims', icon: 'file-text' },
    { id: 'mkt', name: 'Marketing Cloud', sub: 'marketing', icon: 'mail' }
  ] : [
    { id: 'portal', name: 'Member portal', sub: 'web sign-ups', icon: 'globe' },
    { id: 'contact', name: 'Contact centre', sub: 'phone calls', icon: 'headset' },
    { id: 'claims', name: 'Claims', sub: 'claims system', icon: 'file-text' },
    { id: 'mkt', name: 'Marketing', sub: 'mailing lists', icon: 'mail' }
  ];
  const terms = sf
    ? { profile: 'unified individual', profiles: 'unified individuals', rules: 'identity resolution ruleset (match rules)', ruleShort: 'match rule', source: 'data stream', sources: 'Data Cloud data streams' }
    : { profile: 'unified profile', profiles: 'unified profiles', rules: 'match rules', ruleShort: 'match rule', source: 'source system', sources: 'source systems' };
  const people = [
    { id: 'P1', name: 'Maria Lopez', note: 'the member with duplicate letters' },
    { id: 'P2', name: 'Maria Lopes', note: 'a different member with a similar name' },
    { id: 'P3', name: 'Mario Lopez', note: 'lives with Maria Lopez' }
  ];
  // [id, source index, name, email, phone, date of birth, address, true person, quirk]
  const R = [
    ['R1', 0, 'Maria Lopez', 'maria.lopez@mail.com', '555-0142', '1984-03-12', '14 Oak Lane', 'P1', ''],
    ['R2', 0, 'Maria Lopes', 'mlopes@mail.com', '555-0178', '1981-07-30', '220 River Rd', 'P2', ''],
    ['R3', 0, 'Mario Lopez', 'mario.l@mail.com', '555-0163', '1981-07-30', '14 Oak Lane', 'P3', 'same DOB as Maria Lopes'],
    ['R4', 1, 'Mia Lopez', '', '555-0100', '1984-03-12', '14 Oak Ln', 'P1', 'nickname, home phone'],
    ['R5', 1, 'Mario Lopez', '', '555-0100', '1981-07-30', '14 Oak Lane', 'P3', 'shared home phone'],
    ['R6', 1, 'Maria Lopes', '', '555-0178', '1981-07-30', '220 River Rd', 'P2', 'no email'],
    ['R7', 2, 'Maira Lopez', '', '555-0187', '1984-03-12', '14 Oak Lane', 'P1', 'typo, old phone'],
    ['R8', 2, 'Maria Lopes', '', '555-0178', '1981-07-30', '220 River Road', 'P2', 'no email'],
    ['R9', 2, 'Mario Lopez', '', '555-0163', '1981-07-30', '14 Oak Lane', 'P3', 'no email'],
    ['R10', 3, 'Maria Lopez', 'maria.lopez@mail.com', '555-0142', '1984-03-12', '14 Oak Lane', 'P1', ''],
    ['R11', 3, 'maria lopes', 'MLopes@mail.com', '', '1981-07-30', '220 River Rd', 'P2', 'no phone']
  ];
  const records = R.map(([id, src, name, email, phone, dob, address, person, quirk], i) => ({ i, id, src, source: sources[src].name, name, email, phone, dob, address, person, quirk }));
  // Fuzzy name: lower case, nickname map, optimal string alignment distance (a swap of two letters counts once)
  const NICK = { mia: 'maria' };
  const norm = s => s.toLowerCase().trim().split(/\s+/).map((w, k) => (k === 0 && NICK[w]) || w).join(' ');
  const osa = (a, b) => {
    const d = Array.from({ length: a.length + 1 }, (_, i) => [i].concat(Array(b.length).fill(0)));
    for (let j = 1; j <= b.length; j++) d[0][j] = j;
    for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
      const c = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
    return d[a.length][b.length];
  };
  const THRESHOLD = 0.85;
  const nameSim = (a, b) => { const x = norm(a), y = norm(b); return 1 - osa(x, y) / Math.max(x.length, y.length); };
  const em = s => s.trim().toLowerCase();
  const rules = [
    { label: 'Exact email only', short: 'Exact email', how: 'Two records match only when their email addresses are identical.' },
    { label: 'Email or phone', short: 'Email or phone', how: 'Two records match when they share an email address or a phone number.' },
    { label: 'Name + date of birth (fuzzy name)', short: 'Name + DOB', how: 'Two records match when their names are at least 85 % similar and the date of birth is identical.' },
    { label: 'Fuzzy name only', short: 'Fuzzy name', how: 'Two records match when their names are at least 85 % similar. Nothing else is checked.' }
  ];
  const reasonOf = (a, b) => {
    const sameEmail = a.email && b.email && em(a.email) === em(b.email), samePhone = a.phone && b.phone && a.phone === b.phone;
    const sim = nameSim(a.name, b.name) >= THRESHOLD;
    if (rule === 0) return sameEmail ? 'same email' : null;
    if (rule === 1) return sameEmail ? 'same email' : samePhone ? 'same phone' : null;
    if (rule === 2) return sim && a.dob === b.dob ? 'name + DOB' : null;
    return sim ? 'similar name' : null;
  };
  const pairs = [];
  for (let i = 0; i < records.length; i++) for (let j = i + 1; j < records.length; j++) {
    const reason = reasonOf(records[i], records[j]);
    if (reason) pairs.push({ a: i, b: j, reason, sim: +nameSim(records[i].name, records[j].name).toFixed(2) });
  }
  // Union-find over the matching pairs
  const parent = records.map((_, i) => i);
  const find = x => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  pairs.forEach(e => { const ra = find(e.a), rb = find(e.b); if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); });
  const groups = new Map();
  records.forEach((r, i) => { const k = find(i); if (!groups.has(k)) groups.set(k, []); groups.get(k).push(i); });
  const adj = (x, y) => pairs.find(e => (e.a === x && e.b === y) || (e.a === y && e.b === x));
  // Order each profile as a chain of matches where possible; each later card links to one earlier card
  const profiles = [...groups.values()].map((members, k) => {
    // Prefer a path that visits every record so each link joins neighbouring cards (small groups: plain search)
    let budget = 20000, path = null;
    const walk = seq => {
      if (path || --budget < 0) return;
      if (seq.length === members.length) { path = seq; return; }
      members.forEach(x => { if (!path && !seq.includes(x) && adj(seq[seq.length - 1], x)) walk(seq.concat(x)); });
    };
    members.forEach(s => walk([s]));
    const order = path ? [path[0]] : [members[0]], links = [];
    if (path) path.slice(1).forEach((x, k) => { links.push({ a: path[k], b: x, reason: adj(path[k], x).reason }); order.push(x); });
    while (order.length < members.length) {
      const last = order[order.length - 1], rest = members.filter(x => !order.includes(x));
      let next = rest.find(x => adj(last, x)), from = last;
      if (next === undefined) for (const x of rest) { const f = order.find(o => adj(o, x)); if (f !== undefined) { next = x; from = f; break; } }
      links.push({ a: from, b: next, reason: adj(from, next).reason });
      order.push(next);
    }
    const ppl = [...new Set(order.map(i => records[i].person))].sort();
    const names = order.map(i => records[i].name), top = names.slice().sort((a, b) => names.filter(n => n === b).length - names.filter(n => n === a).length)[0];
    return { id: k + 1, records: order, links, people: ppl, label: top };
  });
  const total = id => records.filter(r => r.person === id).length;
  profiles.forEach(pr => {
    pr.status = pr.people.length > 1 ? 'merge' : pr.records.length === total(pr.people[0]) ? 'correct' : 'split';
  });
  const perPerson = people.map(pp => ({ id: pp.id, name: pp.name, profiles: profiles.filter(pr => pr.people.includes(pp.id)).length }));
  const metrics = {
    profiles: profiles.length, people: people.length, pairs: pairs.length,
    correct: profiles.filter(pr => pr.status === 'correct').length,
    falseMerges: profiles.filter(pr => pr.status === 'merge').length,
    mixedPeople: profiles.reduce((a, pr) => a + (pr.people.length > 1 ? pr.people.length : 0), 0),
    missed: perPerson.reduce((a, pp) => a + pp.profiles - 1, 0)
  };
  records.forEach(r => { r.profile = profiles.find(pr => pr.records.includes(r.i)).id; });
  const n = metrics.profiles, P = n === 1 ? terms.profile : terms.profiles;
  const steps = [
    { id: 'intro', t: 0, title: 'Who is Maria?', note: 'Maria Lopez gets two or three copies of every letter. Her health plan keeps her in four ' + terms.sources + ' that do not agree.' },
    { id: 'arrive', t: 3.2, title: 'Records arrive', note: '11 records from 4 ' + terms.sources + ': a nickname, a typo, an old phone, missing emails, a shared home phone.' },
    { id: 'rule', t: 7.6, title: 'Apply the ' + terms.ruleShort, note: rules[rule].how },
    { id: 'match', t: 10.2, title: 'Records link up', note: pairs.length + ' matching pairs link the 11 records into ' + n + (n === 1 ? ' group' : ' groups') + '. Links chain: if A matches B and B matches C, all three join.' },
    { id: 'profiles', t: 14.4, title: n + ' ' + P, note: n + ' ' + P + ' for the plan to write to. It looks tidy. Is it right?' },
    { id: 'reveal', t: 16.8, title: 'The truth: 3 real people', note: metrics.correct + ' of 3 people resolved correctly, ' + metrics.falseMerges + (metrics.falseMerges === 1 ? ' false merge, ' : ' false merges, ') + metrics.missed + (metrics.missed === 1 ? ' duplicate.' : ' duplicates.') },
    { id: 'sowhat', t: 20.2, title: 'So what for architects', note: 'Match rules are a business decision with privacy risk, not a technical default.' }
  ];
  const duration = 23.5;
  const summary = rules[rule].short + ': ' + (metrics.falseMerges
    ? metrics.falseMerges + ' false merge (' + metrics.mixedPeople + ' people in one ' + terms.profile + ')' + (metrics.missed ? ' and ' + metrics.missed + ' duplicates' : '') + '. One member could see another member\'s claims.'
    : metrics.missed ? n + ' ' + P + ' for 3 people: ' + metrics.missed + ' duplicates, no false merges. The letters keep doubling.'
      : n + ' ' + P + ' for 3 people, all correct: no false merges, no duplicates.');
  return {
    rule, ruleLabel: rules[rule].label, ruleShort: rules[rule].short, ruleHow: rules[rule].how, threshold: THRESHOLD,
    salesforce: sf, terms, sources, people, records, pairs, profiles, perPerson, metrics,
    steps, duration, markers: steps.map(s => s.t), summary
  };
}

