function check(p) {
  const m = model(p), n = m.records.length, pl = (k, w) => k + ' ' + w + (k === 1 ? '' : 's');
  // Connected components of the matching pairs, found again by depth-first search (independent of union-find)
  const nb = m.records.map(() => []);
  m.pairs.forEach(e => { nb[e.a].push(e.b); nb[e.b].push(e.a); });
  const comp = Array(n).fill(-1); let c = 0;
  for (let s = 0; s < n; s++) if (comp[s] < 0) { const st = [s]; comp[s] = c; while (st.length) { const x = st.pop(); nb[x].forEach(y => { if (comp[y] < 0) { comp[y] = c; st.push(y); } }); } c++; }
  const key = arr => arr.slice().sort((a, b) => a - b).join(',');
  const want = new Set(Array.from({ length: c }, (_, k) => key(m.records.filter((_, i) => comp[i] === k).map(r => r.i))));
  const got = m.profiles.map(pr => key(pr.records));
  const sameGroups = got.length === want.size && got.every(g => want.has(g));
  const counts = Array(n).fill(0); m.profiles.forEach(pr => pr.records.forEach(i => counts[i]++));
  const oncePer = counts.every(k => k === 1);
  const linksOk = m.profiles.every(pr => pr.links.length === pr.records.length - 1 && pr.links.every(l => m.pairs.some(e => (e.a === l.a && e.b === l.b) || (e.a === l.b && e.b === l.a))));
  // Metrics against the ground truth
  const truth = m.people.map(pp => key(m.records.filter(r => r.person === pp.id).map(r => r.i)));
  const correct = got.filter(g => truth.includes(g)).length;
  const falseMerges = m.profiles.filter(pr => new Set(pr.records.map(i => m.records[i].person)).size > 1).length;
  const missed = m.people.reduce((a, pp) => a + new Set(m.records.filter(r => r.person === pp.id).map(r => r.profile)).size - 1, 0);
  const metricsOk = correct === m.metrics.correct && falseMerges === m.metrics.falseMerges && missed === m.metrics.missed;
  const defaultOk = m.rule !== 2 || (correct === 3 && falseMerges === 0 && missed === 0 && m.profiles.length === 3);
  return {
    pass: sameGroups && oncePer && linksOk && metricsOk && defaultOk,
    detail: m.ruleShort + ': ' + pl(m.pairs.length, 'matching pair') + ' form ' + pl(c, 'connected group') + ' and the model has ' + pl(m.profiles.length, 'profile') + (sameGroups ? ' (the same groups)' : ' (MISMATCH)') +
      ', each of the ' + n + ' records ' + (oncePer ? 'in exactly one' : 'NOT in exactly one') + '; against the truth ' + correct + ' correct, ' + pl(falseMerges, 'false merge') + ', ' + pl(missed, 'duplicate') + '.'
  };
}
